#include <limits>
#include <iostream>

template <typename T>
void check_type() {
    if (std::numeric_limits<T>::is_integer) {
        std::cout << (std::numeric_limits<T>::is_signed ? "Signed " : "Unsigned ") 
                  << "Integer. Exact: " << std::boolalpha 
                  << std::numeric_limits<T>::is_exact << "\n";
    } else {
        std::cout << "Floating Point. Exact: " << std::boolalpha 
                  << std::numeric_limits<T>::is_exact << "\n";
    }
}

int main() {
    check_type<int>();
    check_type<unsigned int>();
    check_type<double>();
}
